package app.dayflow;
import android.widget.*;import org.json.*;import java.util.*;
/** Explicitly selected raw inputs -> one Agent session -> pending results -> native human editor. */
final class InboxAgent {
 static void quick(MainActivity a){try{LinearLayout page=a.fullPage("通知与群聊交给AI",a::showInbox);page.addView(Ui.help(a,"所选来源的待处理原文将发送到配置的模型，AI只生成待核验候选。"));LinkedHashSet<String> sources=new LinkedHashSet<>(),groups=new LinkedHashSet<>();for(int offset=0;;offset+=50){JSONArray rows=Data.get(a).inboxPage(offset);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.optString("source").isEmpty())sources.add(r.optString("source"));if(!r.optString("source_group").isEmpty())groups.add(r.optString("source_group"));}if(rows.length()<50)break;}List<String> sourceNames=new ArrayList<>();sourceNames.add("全部软件 / 短信");sourceNames.addAll(sources);List<String> groupNames=new ArrayList<>();groupNames.add("全部会话");groupNames.addAll(groups);Spinner source=TaskTypes.spinner(a,page,"来源软件",sourceNames),group=TaskTypes.spinner(a,page,"群聊 / 会话",groupNames);
 page.addView(Ui.button(a,"一键发送并生成待核验日程",true,()->{String software=source.getSelectedItemPosition()==0?null:sourceNames.get(source.getSelectedItemPosition()),conversation=group.getSelectedItemPosition()==0?null:groupNames.get(group.getSelectedItemPosition());LinkedHashSet<String> selected=new LinkedHashSet<>();try{for(int offset=0;;offset+=50){JSONArray rows=Data.get(a).inboxPage(offset);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if((software==null||software.equals(r.optString("source")))&&(conversation==null||conversation.equals(r.optString("source_group")))&&!"confirmed".equals(r.optString("confirmation_status")))selected.add(r.getString("id"));}if(rows.length()<50)break;}run(a,selected);}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"手动勾选部分信息",false,()->show(a)));}catch(Exception e){a.message(e.getMessage());}}
 static void show(MainActivity a){page(a,0,new LinkedHashSet<>());}
 private static void page(MainActivity a,int offset,LinkedHashSet<String> selected){try{JSONArray rows=Data.get(a).inboxPage(offset);LinearLayout page=a.fullPage("选择要整理的信息",a::showInbox);page.addView(Ui.text(a,"Agent总结与日程候选",22,true));page.addView(Ui.help(a,"选择原始通知、短信或群聊消息，再交给同一个Agent整理。所选原文会发送到当前模型。生成结果必须进入人工核验编辑，原始信息保留。"));
  page.addView(Ui.button(a,"交给日栖总结并生成候选",true,()->run(a,selected)));TextView count=Ui.help(a,"已选 "+selected.size()+" 条 · 当前第 "+(offset/50+1)+" 页");page.addView(count);
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String id=r.getString("id");com.google.android.material.checkbox.MaterialCheckBox check=new com.google.android.material.checkbox.MaterialCheckBox(a);check.setText(r.optString("title")+"\n"+r.optString("source")+(r.optString("source_group").isEmpty()?"":" · "+r.optString("source_group")));check.setChecked(selected.contains(id));check.setOnCheckedChangeListener((v,on)->{if(on)selected.add(id);else selected.remove(id);count.setText("已选 "+selected.size()+" 条 · 当前第 "+(offset/50+1)+" 页");});page.addView(check);}
  page.addView(Ui.button(a,"选择本页全部",false,()->{for(int i=0;i<rows.length();i++)selected.add(rows.optJSONObject(i).optString("id"));page(a,offset,selected);}));if(offset>0)page.addView(Ui.button(a,"上一页",false,()->page(a,Math.max(0,offset-50),selected)));if(rows.length()==50)page.addView(Ui.button(a,"下一页",false,()->page(a,offset+50,selected)));if(rows.length()==0)page.addView(Ui.help(a,"本页没有待确认信息。"));
 }catch(Exception e){a.message(e.getMessage());}}
 private static void run(MainActivity a,Set<String> selected){if(selected.isEmpty()){a.message("请先选择要整理的信息");return;}final JSONObject[] context={null};a.job(()->{StringBuilder text=new StringBuilder();JSONArray sources=new JSONArray();for(String id:selected){JSONObject r=Data.get(a).find(id);if(r==null||r.optBoolean("deleted")||!r.optString("kind").equals("inbox"))continue;sources.put(new JSONObject().put("id",id).put("revision",r.optString("revision")));text.append("\n--- 原始信息 ---\n").append(r.optString("title")).append("\n来源：").append(r.optString("source")).append(" · ").append(r.optString("source_group")).append("\n资料时间：").append(r.optString("source_time",r.optString("captured_at",r.optString("created_at","未知")))).append("\n").append(r.optString("content")).append('\n');}if(sources.length()==0)throw new Exception("所选信息已被处理，请刷新");context[0]=new JSONObject().put("title","收集箱批量整理").put("content",text.toString()).put("source_ids",sources);return "已准备 "+sources.length()+" 条资料";},()->AssistantPlugin.review(a,context[0],"总结所选通知和群聊，合并同一事项，分别提取活动及截止时间，生成待人工核验的日程候选。不要将不确定信息当成确定时间。"));}
}
